import{_ as e,o as n,c as r,l as o,t as a,N as s}from"./chunks/framework.CMqbtke2.js";const b=JSON.parse('{"title":"nl | x-cmd man (man1) | number lines of files","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | nl - number lines of files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"nl | x-cmd man (man1) | number lines of files"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | nl - number lines of files"}]]},"headers":[],"params":{"isMan":true,"man":"nl","category":"man1","desc":"number lines of files"},"relativePath":"man1/nl.md","filePath":"man1/nl.md"}'),d={name:"man1/nl.md"},i={class:"visually-hidden"},l=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>nl - number lines of files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>nl</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Write each FILE to standard output, with line numbers added.</p><p>With no FILE, or when FILE is -, read standard input.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-b</strong>, <strong>--body-numbering</strong>=<em>STYLE</em></dt><dd>use STYLE for numbering body lines</dd><dt><strong>-d</strong>, <strong>--section-delimiter</strong>=<em>CC</em></dt><dd>use CC for logical page delimiters</dd><dt><strong>-f</strong>, <strong>--footer-numbering</strong>=<em>STYLE</em></dt><dd>use STYLE for numbering footer lines</dd><dt><strong>-h</strong>, <strong>--header-numbering</strong>=<em>STYLE</em></dt><dd>use STYLE for numbering header lines</dd><dt><strong>-i</strong>, <strong>--line-increment</strong>=<em>NUMBER</em></dt><dd>line number increment at each line</dd><dt><strong>-l</strong>, <strong>--join-blank-lines</strong>=<em>NUMBER</em></dt><dd>group of NUMBER empty lines counted as one</dd><dt><strong>-n</strong>, <strong>--number-format</strong>=<em>FORMAT</em></dt><dd>insert line numbers according to FORMAT</dd><dt><strong>-p</strong>, <strong>--no-renumber</strong></dt><dd>do not reset line numbers for each section</dd><dt><strong>-s</strong>, <strong>--number-separator</strong>=<em>STRING</em></dt><dd>add STRING after (possible) line number</dd><dt><strong>-v</strong>, <strong>--starting-line-number</strong>=<em>NUMBER</em></dt><dd>first line number for each section</dd><dt><strong>-w</strong>, <strong>--number-width</strong>=<em>NUMBER</em></dt><dd>use NUMBER columns for line numbers</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Default options are: <strong>-bt</strong> <strong>-d</strong>&#39;\\:&#39; <strong>-fn</strong> <strong>-hn</strong> <strong>-i1</strong><strong>-l1</strong> <strong>-n</strong>&#39;rn&#39; <strong>-s</strong>&lt;TAB&gt; <strong>-v1</strong> <strong>-w6</strong></p><p>CC are two delimiter characters used to construct logical page delimiters; a missing second character implies &#39;:&#39;. As a GNU extension one can specify more than two characters, and also specifying the empty string (<strong>-d</strong> &#39;&#39;) disables section matching.</p><p>STYLE is one of:</p><dl><dt>a</dt><dd>number all lines</dd><dt>t</dt><dd>number only nonempty lines</dd><dt>n</dt><dd>number no lines</dd><dt>pBRE</dt><dd>number only lines that contain a match for the basic regular expression, BRE</dd></dl><p>FORMAT is one of:</p><dl><dt>ln</dt><dd>left justified, no leading zeros</dd><dt>rn</dt><dd>right justified, no leading zeros</dd><dt>rz</dt><dd>right justified, leading zeros</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Scott Bartram and David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/nl%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/nl\\</a>&gt; <br> or available locally via: info &#39;(coreutils) nl invocation&#39;</p>',23);function g(t,m,c,h,u,p){return n(),r("div",null,[o("h1",i,a(t.$params.man),1),l])}const T=e(d,[["render",g]]);export{b as __pageData,T as default};
